import { cn } from "@/lib/utils";
import { HOUSING_ICONS, type HousingIconName } from "./housing-icons.generated";

export type { HousingIconName };

/**
 * A single warm-duotone housing icon, sliced from the shared sprite sheet
 * (generated by web/scripts/housing-icons). Fixed-colour PNG duotone that reads
 * on both the warm-white and terminal-black themes — see the icon design spec.
 *
 * @param name  icon id from the manifest (autocompleted)
 * @param size  rendered px (square); the sprite cell is downscaled to this
 */
export function HousingIcon({
  name,
  size = 16,
  className,
  title,
}: {
  name: HousingIconName;
  size?: number;
  className?: string;
  title?: string;
}) {
  const pos = HOUSING_ICONS.icons[name];
  if (!pos) return null;
  const scale = size / HOUSING_ICONS.cell;
  // Icons always sit beside their text label, so they're decorative by default
  // (aria-hidden). Pass `title` only for a genuinely standalone, label-less icon.
  const a11y = title ? { role: "img", "aria-label": title } : { "aria-hidden": true };
  return (
    <span
      {...a11y}
      className={cn("inline-block shrink-0 align-[-0.15em]", className)}
      style={{
        width: size,
        height: size,
        backgroundImage: `url(${HOUSING_ICONS.sheet})`,
        backgroundRepeat: "no-repeat",
        backgroundSize: `${HOUSING_ICONS.width * scale}px ${HOUSING_ICONS.height * scale}px`,
        backgroundPosition: `-${pos.x * scale}px -${pos.y * scale}px`,
      }}
    />
  );
}
